def experiment(inputs):
    import random
    import math
    params = inputs.get('parameters', {})
    feedback_intensity = params.get('feedback_intensity', 0.5)
    seeds = inputs.get('seeds', [13, 71, 43, 101])
    results = []
    for seed in seeds:
        rng = random.Random(seed)
        val = rng.gauss(0, 1)
        for _ in range(10):
            val = val + math.tanh(val ** 3) * feedback_intensity + rng.gauss(0, 0.1)
        results.append(val)
    mean = sum(results) / len(results)
    variance = sum((x - mean) ** 2 for x in results) / len(results)
    return {
        "measurements": {
            "measurement_validity": [True],
            "distributional_spread": [variance]
        }
    }
